import{_ as s,l as r,o as e,c as n,v as i,p,x as t,d as l,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const V=JSON.parse('{"title":"Viewstamped Replication","description":"","frontmatter":{"title":"Viewstamped Replication","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/viewstamped-replication.md","filePath":"cs/viewstamped-replication.md","lastUpdated":1789023840000}'),m={name:"cs/viewstamped-replication.md"};function h(v,a,R,_,f,E){const o=r("Mermaid");return e(),n("div",null,[a[1]||(a[1]=i('<h1 id="viewstamped-replication" tabindex="-1">Viewstamped Replication <a class="header-anchor" href="#viewstamped-replication" aria-label="Permalink to &quot;Viewstamped Replication&quot;">​</a></h1><div class="epigraph"><p>视图号换主：同一视图里主指定序号，备份按序执行。Paxos 之前，Liskov 组已经用视图与副本做 RSM。</p><footer>—— 据 Oki and Liskov, Viewstamped Replication, PODC 1988；Liskov and Cowling, VR Revisited, 2012 整理</footer></div><p>上一课<a href="/cs/zab-zookeeper">Zab</a>用纪元切主。缺口是<strong>谱系</strong>：Raft/Zab 的「任期+主」不是 2010 年代才发明。VR 用 viewstamp（视图, 序号）标识请求。本课对照，不重写 Raft 选举超时。后课 PBFT 把视图更换升级到拜占庭。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>正常模式：主赋 op-number，发给备份，备份 accept 后主提交、执行、应答。视图更换：备份怀疑主，推进 view-number，收集日志证书，新主带着最高证书上任，未提交请求可能重做。viewstamp 让客户端检测重复与 fencing 旧主。</p><p>缺口：与 Paxos 的对应——view 像 ballot/term，op-number 像槽。VR 从复制算法写起，Paxos 从单值共识写起，后来汇合到同一工程形状。</p><p><span class="marginnote">1988 论文与 2012 的 VR Revisited（修正与清晰化）应一起读。Van Renesse 等有对照 Paxos/VR/Zab 的讲解。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>恢复：崩溃节点用状态传输对齐。组重配置在 revisited 里补。客户端把 view 放进 RPC，旧 view 的应答可丢。</p>',9)),(e(),p(c,null,{default:t(()=>[d(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20V%5B%22%E8%A7%86%E5%9B%BE%20v%22%5D%20--%3E%20PRI%5B%22%E8%AF%A5%E8%A7%86%E5%9B%BE%E7%9A%84%E4%B8%BB%22%5D%0A%20%20PRI%20--%3E%20OP%5B%22op-number%20%E5%BA%8F%E5%88%97%22%5D%0A%20%20SUS%5B%22%E6%80%80%E7%96%91%22%5D%20--%3E%20VC%5B%22%E8%A7%86%E5%9B%BE%E6%9B%B4%E6%8D%A2%22%5D%0A%20%20VC%20--%3E%20V2%5B%22%E8%A7%86%E5%9B%BE%20v%2B1%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<p>与<a href="/cs/leases">租约</a>：VR 原版靠超时做怀疑，没有强租约读优化；工程上可加。与链式复制：VR 是星形主，不是链。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>安全：同一视图内主唯一指定序号；跨视图靠证书证明已复制的前缀。这与 Raft 「当前任期多数派才提交」是同一类「防旧主幽灵提交」，规则表述不同。实现敏感点同样是：哪些未提交条目在 view change 后仍必须保留。</p><p>本课不把 VR 写成比 Raft 更弱或更强的营销。教学价值是：状态机复制的最小词汇——视图、主、序号、更换——在 1988 已齐。</p><p>拜占庭下一课：PBFT 的 view change 是 VR 的恶意版，证书要防伪造。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 2012 修订的全部消息列表。不引入 HARP。后课默认：说到 viewstamp，就是 VR 的 (view, op)；Raft term/index、Zab epoch/ZXID、Paxos ballot/slot 是同一族坐标。PBFT 在坐标上加三阶段认证。</p><p>换主协议是共识的控制面。数据面只是带序号的操作流。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>VR：视图内主序号，视图更换用日志证书。</li><li>与 Paxos/Raft/Zab 同族，表述从复制出发。</li><li>viewstamp 给客户端 fencing 与去重。</li><li>出处：Oki and Liskov, PODC 1988；Liskov and Cowling, 2012。</li></ul>',10))])}const B=s(m,[["render",h]]);export{V as __pageData,B as default};
